begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\ir fixtures/push-keys.inc
create function pg_temp.account() returns jsonb language sql as $$select api.account_app_snapshot('duindorp-halloween-2026')$$;
create function pg_temp.command(action text,payload jsonb) returns jsonb language sql as $$select api.account_app_command('duindorp-halloween-2026',action,payload)$$;
grant execute on function pg_temp.account(),pg_temp.command(text,jsonb) to authenticated;
select ok(not has_function_privilege('anon','api.account_app_snapshot(text)','execute'),'anonymous users cannot retrieve account links');
select ok(not has_table_privilege('authenticated','app_private.account_app_preferences','select'),'preferences are private behind verified account RPC');
select ok(not has_function_privilege('authenticated','api.participant_guidance_before_account_app(text,text,text,jsonb)','execute'),'legacy wrapper cannot bypass new read contract');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is(pg_temp.account()->'environments'->0->>'id','parent','existing OTP user retains the existing parent environment');
select is(jsonb_array_length(pg_temp.account()->'children'),1,'only own registered child is listed');
select throws_ok($$select pg_temp.command('remember','{"kind":"adult","id":"organization"}')$$,'42501','NOT_AUTHORIZED','client cannot invent an organization role');
select throws_ok($$select pg_temp.command('remember','{"kind":"child","id":"25000002-0000-0000-0000-000000000001"}')$$,'42501','NOT_AUTHORIZED','other family child cannot be selected');
select is(pg_temp.command('remember','{"kind":"adult","id":"parent"}')->>'path','/omgeving/meeloper/nu','remember returns a server-owned path');
select is(pg_temp.account()->'resume','{"kind":"adult","id":"parent"}'::jsonb,'resume is a preference checked against current roles');
select is(api.participant_guidance('duindorp-halloween-2026','acknowledge')->>'welcomeVersion','1','read confirmation is stored for the verified account and event');
select is(api.participant_guidance('duindorp-halloween-2026')->>'welcomeVersion','1','reload keeps the welcome read');
select throws_ok($$select pg_temp.command('welcome','{"version":99}')$$,'P0001','WELCOME_VERSION_CHANGED','unknown explanation versions cannot be acknowledged');
set local role postgres;
update app_private.community_acknowledgements set local_day=current_date-1 where user_id='a0000000-0000-0000-0000-000000000001';
set local role authenticated;
select is(api.participant_guidance('duindorp-halloween-2026')->>'welcomeVersion','1','a different calendar day does not repeat the welcome');
select is(pg_temp.command('remember',jsonb_build_object('kind','child','id',pg_temp.account()->'children'->0->>'id'))->>'path','/poortenboek','child resume uses the existing protected child flow');
set local role postgres;
update app_private.household_members set revoked_at=now() where user_id='a0000000-0000-0000-0000-000000000001';
set local role authenticated;
select is(pg_temp.account()->'resume','null'::jsonb,'revoked child relationship removes the stored resume');
select is(jsonb_array_length(pg_temp.account()->'children'),0,'revoked child relationship removes the dropdown child');
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select ok(exists(select 1 from jsonb_array_elements(pg_temp.account()->'environments') e where e->>'kind'='house'),'house owner sees their real gate');
select ok(not exists(select 1 from jsonb_array_elements(pg_temp.account()->'environments') e where e->>'kind' in ('parent','admin')),'house ownership grants no parent or organization role');
select is(jsonb_array_length(pg_temp.account()->'children'),0,'house owner does not receive arbitrary children');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000011","role":"authenticated"}',true);
select is(pg_temp.account()->'environments','[]'::jsonb,'unknown account has no fictional participation');
select set_config('request.jwt.claims','{"sub":"f0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select ok(exists(select 1 from jsonb_array_elements(pg_temp.account()->'environments') e where e->>'kind'='admin'),'organization environment requires actual capabilities');
select is(api.participant_guidance('duindorp-halloween-2026','acknowledge')->>'welcomeVersion','1','organization-only users can read the same welcome');
select lives_ok($$select api.push_subscription_upsert('https://fcm.googleapis.com/fcm/send/account-device-fixture',pg_temp.push_fixture_key(),repeat('A',22),'fixture','fixture')$$,'real push subscription admission accepts a valid isolated fixture');
select is(api.account_push_device('duindorp-halloween-2026',encode(extensions.digest('https://fcm.googleapis.com/fcm/send/account-device-fixture','sha256'),'hex'))->>'registered','true','current device is active only after server registration');
select set_config('request.jwt.claims','{"sub":"e0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is(api.account_push_device('duindorp-halloween-2026',encode(extensions.digest('https://fcm.googleapis.com/fcm/send/account-device-fixture','sha256'),'hex'))->>'registered','false','another account cannot claim a previous device registration');
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select pg_temp.account()$$,'42501','NOT_AUTHORIZED','a child cookie alone does not authenticate an adult account');
select * from finish();
rollback;
